const item = $input.first().json;

// Recover chatId/body fields directly from the Webhook Trigger node as a fallback,
// since voice-processing nodes (Transcribe Voice, Decode Webhook Audio) overwrite
// $json along the way and can lose fields from the original trigger payload.
let webhookBody = null;

try {
  const arr = $items('Webhook Trigger', 0, 0);
  if (arr && arr.length) webhookBody = arr[0].json.body;
} catch (e) {}

let userText = item.body?.input ?? item.text ?? item.output ?? item.content ?? '';

const chatId = item.body?.chatId
  ?? webhookBody?.chatId
  ?? item.sessionId
  ?? 'anonymous';

const topicId = item.body?.topicId ?? item.topicId ?? webhookBody?.topicId ?? undefined;
const model = item.body?.model ?? item.model ?? webhookBody?.model ?? 'gemini-3-flash-preview';
const requester = item.body?.requester ?? item.requester ?? webhookBody?.requester ?? undefined;
const patientId = item.body?.patientId ?? item.patientId ?? webhookBody?.patientId ?? undefined;
const medplumToken = item.body?.medplumToken ?? item.medplumToken ?? webhookBody?.medplumToken ?? undefined;
const messages = item.body?.messages ?? item.messages ?? webhookBody?.messages ?? [];

// normalize `type` — any unrecognized value falls back to 'translator'
const rawType = item.body?.type ?? item.type ?? webhookBody?.type ?? 'translator';
const validTypes = ['summary', 'translator', 'visualizer'];
const type = validTypes.includes(rawType) ? rawType : 'translator';

// this workflow is webhook-only; source is always 'webhook'
const source = 'webhook';
const voiceSource = item._voiceSource === true;
const replyWithVoice = item.body?.replyWithVoice ?? webhookBody?.replyWithVoice ?? voiceSource;

return [{ json: { userText, chatId, topicId, model, requester, patientId, medplumToken, type, messages, source, voiceSource, replyWithVoice } }];

