const base64 = $json.candidates[0].content.parts[0].inlineData.data;
const mimeType = $json.candidates[0].content.parts[0].inlineData.mimeType || 'audio/L16;rate=24000';
const rateMatch = mimeType.match(/rate=(\d+)/);
const sampleRate = rateMatch ? parseInt(rateMatch[1]) : 24000;
const numChannels = 1;
const bitsPerSample = 16;

const pcmData = Buffer.from(base64, 'base64');

function createWavHeader(dataLength, sampleRate, numChannels, bitsPerSample) {
  const byteRate = sampleRate * numChannels * bitsPerSample / 8;
  const blockAlign = numChannels * bitsPerSample / 8;
  const buffer = Buffer.alloc(44);
  buffer.write('RIFF', 0);
  buffer.writeUInt32LE(36 + dataLength, 4);
  buffer.write('WAVE', 8);
  buffer.write('fmt ', 12);
  buffer.writeUInt32LE(16, 16);
  buffer.writeUInt16LE(1, 20);
  buffer.writeUInt16LE(numChannels, 22);
  buffer.writeUInt32LE(sampleRate, 24);
  buffer.writeUInt32LE(byteRate, 28);
  buffer.writeUInt16LE(blockAlign, 32);
  buffer.writeUInt16LE(bitsPerSample, 34);
  buffer.write('data', 36);
  buffer.writeUInt32LE(dataLength, 40);
  return buffer;
}

const header = createWavHeader(pcmData.length, sampleRate, numChannels, bitsPerSample);
const wavBuffer = Buffer.concat([header, pcmData]);

return {
  json: {
    audioBase64: wavBuffer.toString('base64'),
    audioMimeType: 'audio/wav'
  }
};

