={{ (() => {
  const uuid = () => 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = Math.random() * 16 | 0;
    return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
  });
  const categoryCode = $fromAI('categoryCode', "'LAB' for a lab order or 'RAD' for an imaging order");
  const notes = $fromAI('notes', 'Order notes (optional)', 'string');
  const occurrenceDateTime = $fromAI('occurrenceDateTime', 'Specimen/study date-time ISO 8601 (optional)', 'string');
  const encounterId = $fromAI('encounterId', 'Encounter resource ID this order is tied to (optional)', 'string');
  const title = $fromAI('title', 'Test/study title');
  const questionnaireId = $fromAI('questionnaireId', 'Questionnaire resource ID from a Resolve/Persist Questionnaire tool');
  const serviceRequestUrn = 'urn:uuid:' + uuid();
  const serviceRequest = {
    resourceType: 'ServiceRequest',
    status: 'active',
    intent: 'order',
    subject: { reference: 'Patient/' + $fromAI('patientId', 'Medplum Patient resource ID') },
    requester: { reference: 'Practitioner/' + $fromAI('requesterId', 'Medplum Practitioner resource ID of the requester') },
    category: [{ coding: [{ system: 'http://terminology.hl7.org/CodeSystem/v2-0074', code: categoryCode, display: categoryCode === 'RAD' ? 'Radiology' : 'Laboratory' }] }],
    code: {
      text: title,
      coding: [{
        system: $fromAI('codeSystem', 'Code system: ai-test-code for a pinned test, loinc.org for a catalog test'),
        code: $fromAI('code', 'Pinned test code or LOINC code'),
        display: title
      }]
    },
    note: notes ? [{ text: notes }] : undefined,
    occurrenceDateTime: occurrenceDateTime || undefined,
    encounter: encounterId ? { reference: 'Encounter/' + encounterId } : undefined,
    authoredOn: new Date().toISOString()
  };
  const task = {
    resourceType: 'Task',
    status: 'requested',
    intent: 'order',
    code: { text: 'Record results: ' + title },
    focus: { reference: 'Questionnaire/' + questionnaireId },
    basedOn: [{ reference: serviceRequestUrn }],
    for: { reference: 'Patient/' + $fromAI('patientId', 'Medplum Patient resource ID') },
    requester: { reference: 'Practitioner/' + $fromAI('requesterId', 'Medplum Practitioner resource ID of the requester') },
    owner: { reference: 'Practitioner/' + $fromAI('assigneeId', 'Medplum Practitioner resource ID of the lab_technician/imaging_technician assignee') },
    authoredOn: new Date().toISOString(),
    input: [{ type: { text: 'Questionnaire' }, valueReference: { reference: 'Questionnaire/' + questionnaireId } }]
  };
  return {
    resourceType: 'Bundle',
    type: 'transaction',
    entry: [
      { fullUrl: serviceRequestUrn, resource: serviceRequest, request: { method: 'POST', url: 'ServiceRequest' } },
      { fullUrl: 'urn:uuid:' + uuid(), resource: task, request: { method: 'POST', url: 'Task' } }
    ]
  };
})() }}

